package org.mockito.internal.invocation;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import org.hamcrest.Matcher;
import org.junit.*;
import org.junit.Test;
import org.mockito.exceptions.PrintableInvocation;
import org.mockito.internal.debugging.Location;
import org.mockito.internal.invocation.Invocation;
import org.mockito.internal.invocation.InvocationMatcher;
import org.mockito.internal.invocation.matchers.Matcher;
import org.mockito.internal.matchers.CapturesArguments;
import org.mockito.internal.reporting.PrintSettings;
import org.mockito.internal.reporting.PrintingFriendlyInvocation;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class InvocationMatcher_captureArgumentsFrom_TriageGen1Test {

    // Mocking the CapturesArguments interface/class behavior as it's used in the method
    public interface CapturesArguments extends Matcher {
        void captureFrom(Object argument);
    }

    // Mocking the Matcher interface as it's used in the loop
    public interface MockMatcher extends Matcher {}

    // Mocking the Invocation interface
    public interface MockInvocation extends Invocation {
        Object[] getArguments();
    }

    // Helper implementation for CapturesArguments to verify calls
    private static class TestCapturesArgument implements CapturesArguments {
        Object capturedValue = null;
        int callCount = 0;

        @Override
        public void captureFrom(Object argument) {
            this.capturedValue = argument;
            this.callCount++;
        }

        @Override
        public boolean matches(Object argument) {
            return true;
        }
    }

    @Test
    public void testCaptureArgumentsFrom_AllMatchersCapture() {
        TestCapturesArgument captor1 = new TestCapturesArgument();
        TestCapturesArgument captor2 = new TestCapturesArgument();
        List<Matcher> matchers = Arrays.asList(captor1, captor2);

        InvocationMatcher matcher = new InvocationMatcher(null, matchers);

        MockInvocation invocation = new MockInvocation() {
            @Override
            public Object[] getArguments() {
                return new Object[]{"arg1", "arg2"};
            }
        };

        matcher.captureArgumentsFrom(invocation);

        assertEquals(1, captor1.callCount);
        assertEquals("arg1", captor1.capturedValue);
        assertEquals(1, captor2.callCount);
        assertEquals("arg2", captor2.capturedValue);
    }

    @Test
    public void testCaptureArgumentsFrom_FewerArgumentsThanMatchers() {
        TestCapturesArgument captor1 = new TestCapturesArgument();
        MockMatcher normalMatcher = new MockMatcher() {
            @Override
            public boolean matches(Object argument) { return true; }
        };
        TestCapturesArgument captor2 = new TestCapturesArgument();

        List<Matcher> matchers = Arrays.asList(captor1, normalMatcher, captor2);
        InvocationMatcher matcher = new InvocationMatcher(null, matchers);

        MockInvocation invocation = new MockInvocation() {
            @Override
            public Object[] getArguments() {
                return new Object[]{"onlyOne"};
            }
        };

        matcher.captureArgumentsFrom(invocation);

        assertEquals(1, captor1.callCount);
        assertEquals("onlyOne", captor1.capturedValue);
        assertEquals(0, captor2.callCount); // k=2, invocation.length=1. 1 > 2 is false.
    }

    @Test
    public void testCaptureArgumentsFrom_MatchersNotInstancesOfCapturesArguments() {
        MockMatcher matcher1 = new MockMatcher() {
            @Override
            public boolean matches(Object argument) { return true; }
        };
        List<Matcher> matchers = Arrays.asList(matcher1);
        InvocationMatcher matcher = new InvocationMatcher(null, matchers);

        MockInvocation invocation = new MockInvocation() {
            @Override
            public Object[] getArguments() {
                return new Object[]{"arg1"};
            }
        };

        // Should not throw ClassCastException
        matcher.captureArgumentsFrom(invocation);
    }

    @Test
    public void testCaptureArgumentsFrom_EmptyMatchers() {
        List<Matcher> matchers = new ArrayList<>();
        InvocationMatcher matcher = new InvocationMatcher(null, matchers);

        MockInvocation invocation = new MockInvocation() {
            @Override
            public Object[] getArguments() {
                return new Object[]{"arg1"};
            }
        };

        matcher.captureArgumentsFrom(invocation);
        // Should simply complete without error
    }

    @Test
    public void testCaptureArgumentsFrom_EmptyArguments() {
        TestCapturesArgument captor = new TestCapturesArgument();
        List<Matcher> matchers = Arrays.asList(captor);
        InvocationMatcher matcher = new InvocationMatcher(null, matchers);

        MockInvocation invocation = new MockInvocation() {
            @Override
            public Object[] getArguments() {
                return new Object[0];
            }
        };

        matcher.captureArgumentsFrom(invocation);
        assertEquals(0, captor.callCount);
    }
}
